      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "我 一直注视着你"
        },
        {
          "id": "V1-02",
          "zh": "仿佛已将孤独放下"
        },
        {
          "id": "V1-03",
          "zh": "今夜 月亮也含笑相迎"
        },
        {
          "id": "V1-04",
          "zh": "朝我这边看"
        },
        {
          "id": "V1-05",
          "zh": "oh, fly me to the star"
        }
